import { DB } from '../state.js';
import { v } from '../utils.js';
import { showToast } from '../toast.js';
import { calcStats } from '../render/vistorias.js';

export async function gerarXLSX() {
  if (!v('c_nome')) { showToast('err', '❌ Preencha o nome da obra'); return; }
  showToast('load', 'Gerando Excel...');
  await new Promise(r => setTimeout(r, 100));
  try {
    const wb = window.XLSX.utils.book_new();
    const addSh = (name, aoa, cw) => {
      const ws = window.XLSX.utils.aoa_to_sheet(aoa);
      if (cw) ws['!cols'] = cw.map(w => ({ wch: w }));
      ws['!pageSetup'] = { paperSize: 9, fitToPage: true, fitToWidth: 1 };
      window.XLSX.utils.book_append_sheet(wb, ws, name);
    };
    const semStr = v('c_sem') || 'XX';
    const iniStr = v('c_ini') ? new Date(v('c_ini')).toLocaleDateString('pt-BR') : '';
    const fimStr = v('c_fim') ? new Date(v('c_fim')).toLocaleDateString('pt-BR') : '';

    addSh('CAPA', [
      ['RELATÓRIO SEMANAL'], [''],
      ['Obra',          v('c_nome')],
      ['Período',       iniStr + ' a ' + fimStr],
      ['Semana',        semStr],
      ['Engenheiro',    v('c_eng')],
      ['Construtora',   v('c_obra')],
      ['Avanço de Entregas', v('c_avanco') + '%'],
    ], [30, 50]);

    if (DB.unidades.length) {
      const c = Object.keys(DB.unidades[0]);
      addSh('UNIDADES', [c, ...DB.unidades.map(r => c.map(k => r[k] || ''))], [16, 14, 14, 32]);
    }
    if (DB.vistorias.length) {
      const c = Object.keys(DB.vistorias[0]);
      addSh('VISTORIAS', [c, ...DB.vistorias.map(r => c.map(k => r[k] || ''))]);
      const s = calcStats(DB.vistorias);
      addSh('VISÃO TOTAL', [
        ['TOTAL', 'APROVADAS', 'REPROVADAS', 'NÃO COMP.', 'TAXA A.', 'TAXA R.', 'TAXA NC'],
        [s.t, s.a, s.r, s.n, s.pa, s.pr, s.pn]
      ], [18, 16, 16, 18, 14, 14, 12]);
    }
    if (DB.delib.length) {
      const c = Object.keys(DB.delib[0]);
      addSh('DELIBERAÇÕES', [c, ...DB.delib.map(r => c.map(k => r[k] || ''))], [16, 14, 45, 14, 14, 12, 18, 14]);
    }
    if (DB.mfo.length) {
      const c = Object.keys(DB.mfo[0]);
      addSh('MFO', [c, ...DB.mfo.map(r => c.map(k => r[k] || ''))], [32, ...Array(c.length - 1).fill(16)]);
    }
    if (DB.checklist.length) {
      const c = Object.keys(DB.checklist[0]);
      addSh('CHECKLIST', [c, ...DB.checklist.map(r => c.map(k => r[k] || ''))], [24, 35, 14, 22, 18, 35]);
    }
    if (v('parecer')) {
      const parecerLinhas = v('parecer').split('\n').map(l => [l]);
      addSh('PARECER', [
        ['PARECER SEMANAL'], [''], ['Semana ' + semStr],
        [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''], [''],
        ...parecerLinhas
      ], [80]);
    }

    window.XLSX.writeFile(wb, 'RLT_SEM' + semStr + '_' + v('c_nome').replace(/\s+/g, '_').toUpperCase() + '.xlsx');
    showToast('ok', '✅ Excel gerado!');
  } catch (e) { showToast('err', '❌ Erro: ' + e.message); }
}

export function baixarTemplateEmBranco() {
  try {
    const wb = window.XLSX.utils.book_new();
    const addSh = (name, headers, cw) => {
      const ws = window.XLSX.utils.aoa_to_sheet([headers]);
      if (cw) ws['!cols'] = cw.map(w => ({ wch: w }));
      window.XLSX.utils.book_append_sheet(wb, ws, name);
    };

    { const wsCapa = window.XLSX.utils.aoa_to_sheet([
      ['CAMPO', 'VALOR', 'INSTRUCAO'],
      ['NOME', '', 'Nome da obra'],
      ['CODIGO', '', 'Codigo interno (ex: OB-2024-017)'],
      ['INI', '', 'Inicio da semana (AAAA-MM-DD)'],
      ['FIM', '', 'Fim da semana (AAAA-MM-DD)'],
      ['SEMANA', '', 'Numero da semana ISO (auto se vazio)'],
      ['ENGENHEIRO', '', 'Engenheiro responsavel'],
      ['CONSTRUTORA', '', 'Nome da construtora'],
      ['PARECER', '', 'Texto do parecer semanal'],
      ['POSITIVOS', '', 'Lista de pontos positivos'],
      ['ATENCAO', '', 'Pontos de atencao / riscos'],
      ['ENCAM', '', 'Encaminhamentos e responsaveis'],
    ]); wsCapa['!cols'] = [{wch:20},{wch:40},{wch:40}]; window.XLSX.utils.book_append_sheet(wb, wsCapa, 'CAPA'); }

    addSh('UNIDADES',     ['BLOCO', 'PAVIMENTO', 'UNIDADE', 'CATEGORIA'],                                        [14, 14, 14, 32]);
    addSh('VISTORIAS',    ['UNIDADE', 'MÊS', 'SEMANA Nº', 'DATA VISTORIA', 'STATUS', 'MOTIVO REPROVAÇÃO'],       [14, 14, 12, 16, 20, 36]);
    addSh('DELIBERAÇÕES', ['#', 'DELIBERAÇÃO', 'RESPONSÁVEL', 'PRAZO', 'STATUS', 'DELTA'],                       [6,  50, 20, 14, 16, 10]);
    addSh('MFO',          ['CATEGORIA', 'PREVISTO', 'REALIZADO', 'DESVIO', 'DESVIO %'],                          [32, 18, 18, 18, 12]);
    addSh('CHECKLIST',    ['ITEM', 'DESCRIÇÃO', 'DATA', 'STATUS', 'RESPONSÁVEL', 'OBSERVAÇÃO'],                  [10, 40, 14, 20, 20, 40]);

    window.XLSX.writeFile(wb, 'MODELO_BASE_SEMANAL_VAZIO.xlsx');
    showToast('ok', '✅ Modelo em branco baixado!');
  } catch (e) { showToast('err', '❌ Erro: ' + e.message); }
}

export function baixarTemplate() {
  try {
    const bin = atob(TEMPLATE_B64);
    const buf = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    const wb = window.XLSX.read(buf, { type: 'array' });
    const capaName = wb.SheetNames.find(n => n.trim().toUpperCase() === 'CAPA');
    if (capaName) {
      const rows = window.XLSX.utils.sheet_to_json(wb.Sheets[capaName], { defval: '', header: 1 });
      const keys = rows.map(r => String(r[0] || '').toUpperCase());
      [['POSITIVOS', '', 'Lista de pontos positivos'], ['ATENCAO', '', 'Pontos de atencao / riscos'], ['ENCAM', '', 'Encaminhamentos e responsaveis']]
        .forEach(row => { if (!keys.includes(row[0])) rows.push(row); });
      const newWs = window.XLSX.utils.aoa_to_sheet(rows);
      newWs['!cols'] = [{ wch: 20 }, { wch: 40 }, { wch: 40 }];
      wb.Sheets[capaName] = newWs;
    }
    const out = window.XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'MODELO_BASE_SEMANAL.xlsx'; a.click();
    URL.revokeObjectURL(url);
    showToast('ok', '✅ Modelo baixado!');
  } catch (e) { showToast('err', '❌ Erro ao baixar: ' + e.message); }
}

// Base64 do arquivo XLSX de exemplo (gerado com dados reais — 240 unidades, 538 vistorias)
const TEMPLATE_B64 = '';
